export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification = "unknown_failure" | "invalid_provider_response" | "repository_failure";
type FailedAt = Provider | "repository";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment = QueuedShipment | DispatchedShipment | DeferredShipment | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: Classification;
  rejections: readonly Rejection[];
}>;

export interface ServiceResponse {
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found";
      };
}

type DispatchCommand = Readonly<{ op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient }>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | DispatchCommand;

type CarrierAttempt =
  | Readonly<{ kind: "confirmed"; provider: Provider; bookingId: string; rejections: readonly Rejection[] }>
  | Readonly<{ kind: "refused"; provider: Provider; reason: RefusalReason; rejections: readonly Rejection[] }>
  | Readonly<{ kind: "throttled"; provider: Provider; retryAtMs: number; rejections: readonly Rejection[] }>
  | Readonly<{
      kind: "aborted";
      provider: Provider;
      classification: Exclude<Classification, "repository_failure">;
      rejections: readonly Rejection[];
    }>;

type ClassifiedCarrierRejection =
  | Readonly<{ kind: "refused"; provider: Provider; reason: RefusalReason }>
  | Readonly<{ kind: "throttled"; provider: Provider; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      provider: Provider;
      classification: Exclude<Classification, "repository_failure">;
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonblankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value);
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    !isNonblankString(value.recipient.name) ||
    !isNonblankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const parsed = value.map((item) => {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    return { provider: item.provider, reason: item.reason };
  });
  return parsed.every((item) => item !== undefined) ? parsed : undefined;
}

function parseStoredShipment(value: unknown): StoredShipment {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isSafeInteger(value.parcelGrams) ||
    value.parcelGrams <= 0
  ) {
    throw new Error("unsupported shipment record");
  }

  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isSafeInteger(value.dispatchedAtMs)
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (value.state === "deferred" && isProvider(value.nextProvider) && isSafeInteger(value.retryAtMs)) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...fields,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return { ...fields, state: "unavailable", rejections };
    }
  }
  throw new Error("unsupported shipment record");
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return { ...fields, state: "unavailable", rejections: shipment.rejections };
  }
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: Classification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections,
  };
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(
  value: unknown,
  nowMs: number,
): ClassifiedCarrierRejection {
  if (!isObject(value)) {
    return { kind: "aborted", provider: "atlas", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (isRefusalReason(value.reason)) {
      return { kind: "refused", provider: "atlas", reason: value.reason };
    }
    return { kind: "aborted", provider: "atlas", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    if (isSafeInteger(value.retryAtMs) && value.retryAtMs > nowMs) {
      return { kind: "throttled", provider: "atlas", retryAtMs: value.retryAtMs };
    }
    return { kind: "aborted", provider: "atlas", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", provider: "atlas", classification: "unknown_failure" };
}

function classifyBeaconRejection(
  value: unknown,
  nowMs: number,
): ClassifiedCarrierRejection {
  if (!isObject(value)) {
    return { kind: "aborted", provider: "beacon", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (isObject(value.details) && isRefusalReason(value.details.reason)) {
      return { kind: "refused", provider: "beacon", reason: value.details.reason };
    }
    return { kind: "aborted", provider: "beacon", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    if (isObject(value.details) && isSafeInteger(value.details.retryAtMs) && value.details.retryAtMs > nowMs) {
      return { kind: "throttled", provider: "beacon", retryAtMs: value.details.retryAtMs };
    }
    return { kind: "aborted", provider: "beacon", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", provider: "beacon", classification: "unknown_failure" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
  rejections: readonly Rejection[],
): Promise<CarrierAttempt> {
  let confirmation: unknown;
  try {
    confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
  } catch (cause) {
    const classified =
      provider === "atlas" ? classifyAtlasRejection(cause, nowMs) : classifyBeaconRejection(cause, nowMs);
    return { ...classified, rejections };
  }

  if (provider === "atlas") {
    if (isObject(confirmation) && isNonemptyString(confirmation.bookingId)) {
      return { kind: "confirmed", provider, bookingId: confirmation.bookingId, rejections };
    }
  } else if (isObject(confirmation) && isNonemptyString(confirmation.reference)) {
    return { kind: "confirmed", provider, bookingId: confirmation.reference, rejections };
  }
  return { kind: "aborted", provider, classification: "invalid_provider_response", rejections };
}

function nextProviderAfterRefusal(provider: Provider): Provider | undefined {
  return provider === "atlas" ? "beacon" : undefined;
}

async function resolveCarrierDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  firstProvider: Provider,
  command: DispatchCommand,
  initialRejections: readonly Rejection[],
): Promise<CarrierAttempt> {
  let provider: Provider | undefined = firstProvider;
  let rejections = initialRejections;
  const attempted = new Set<Provider>();

  while (provider !== undefined && !attempted.has(provider) && !rejections.some((item) => item.provider === provider)) {
    attempted.add(provider);
    const attempt = await attemptCarrier(
      dependencies,
      provider,
      providerRequest(shipment, command.recipient),
      command.nowMs,
      rejections,
    );
    if (attempt.kind !== "refused") {
      return attempt;
    }

    const nextProvider = nextProviderAfterRefusal(attempt.provider);
    if (nextProvider === undefined) {
      return attempt;
    }
    rejections = [...rejections, { provider: attempt.provider, reason: attempt.reason }];
    provider = nextProvider;
  }

  return { kind: "aborted", provider: firstProvider, classification: "unknown_failure", rejections };
}

function eventForAbort(body: AbortBody): Record<string, unknown> {
  return {
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: body.rejections,
  };
}

export function createShippingService(dependencies: ShippingDependencies) {
  function abort(
    shipmentId: string,
    failedAt: FailedAt,
    classification: Classification,
    rejections: readonly Rejection[],
  ): ServiceResponse {
    const body = abortBody(shipmentId, failedAt, classification, rejections);
    dependencies.logger.info(eventForAbort(body));
    return { status: 500, body };
  }

  async function saveDecision(
    shipment: StoredShipment,
    record: StoredShipment,
    event: Record<string, unknown>,
    status: number,
    saveFailureRejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    try {
      await dependencies.repository.save(shipment.id, record);
    } catch {
      return abort(shipment.id, "repository", "repository_failure", saveFailureRejections);
    }
    dependencies.logger.info(event);
    return { status, body: publicShipment(record) };
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return abort(command.shipmentId, "repository", "repository_failure", []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "dispatched") {
      return { status: 200, body: publicShipment(shipment) };
    }
    if (shipment.state === "unavailable") {
      return { status: 422, body: publicShipment(shipment) };
    }
    if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }

    const firstProvider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
    const initialRejections = shipment.state === "deferred" ? shipment.rejections : [];
    const decision = await resolveCarrierDecision(dependencies, shipment, firstProvider, command, initialRejections);

    switch (decision.kind) {
      case "confirmed": {
        const dispatched: DispatchedShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "dispatched",
          provider: decision.provider,
          bookingId: decision.bookingId,
          dispatchedAtMs: command.nowMs,
        };
        return saveDecision(
          shipment,
          dispatched,
          { shipmentId: shipment.id, action: "dispatched", provider: decision.provider },
          200,
          decision.rejections,
        );
      }
      case "throttled": {
        const deferred: DeferredShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "deferred",
          nextProvider: decision.provider,
          retryAtMs: decision.retryAtMs,
          rejections: decision.rejections,
        };
        return saveDecision(
          shipment,
          deferred,
          {
            shipmentId: shipment.id,
            action: "deferred",
            provider: decision.provider,
            retryAtMs: decision.retryAtMs,
            rejections: decision.rejections,
          },
          202,
          decision.rejections,
        );
      }
      case "refused": {
        const rejections = [...decision.rejections, { provider: decision.provider, reason: decision.reason }];
        const unavailable: UnavailableShipment = {
          schemaVersion: 1,
          id: shipment.id,
          routeCode: shipment.routeCode,
          parcelGrams: shipment.parcelGrams,
          state: "unavailable",
          rejections,
        };
        return saveDecision(
          shipment,
          unavailable,
          { shipmentId: shipment.id, action: "unavailable", rejections },
          422,
          rejections,
        );
      }
      case "aborted":
        return abort(shipment.id, decision.provider, decision.classification, decision.rejections);
    }
  }

  return { handle };
}
